"""Render deterministic TypeScript and MDX for the Rust API reference."""

from __future__ import annotations

import json

from markdown_rendering import escape_mdx_table_cell
from rust_api_discovery import RustBinding, RustCrate, RustReference

TS_GENERATED_MARKER = "GENERATED by docs/fern/scripts/gen_rust_api.py -- do not edit."
MDX_GENERATED_MARKER = (
    "{/* GENERATED by docs/fern/scripts/gen_rust_api.py -- do not edit. */}"
)
GROUP_LABELS = {
    "core": "Core Crates",
    "supporting": "Supporting Crates",
    "development": "Development and Testing",
    "deprecated": "Deprecated Crates",
}


def render_ts_data(reference: RustReference) -> str:
    """Render the typed data module used by the Rust browser."""
    header = (
        "/*\n"
        " * SPDX-FileCopyrightText: Copyright (c) 2025-2026 NVIDIA "
        "CORPORATION & AFFILIATES. All rights reserved.\n"
        " * SPDX-License-Identifier: Apache-2.0\n"
        " *\n"
        f" * {TS_GENERATED_MARKER}\n"
        " */\n"
    )
    return (
        f"{header}\n{_type_declarations()}\n"
        f"export const RUST_WORKSPACE_VERSION = "
        f"{json.dumps(reference.workspace_version)};\n\n"
        f"{_crate_array(reference.crates)}\n{_binding_array(reference.bindings)}"
    )


def _type_declarations() -> str:
    """Return the TypeScript contracts for generated Rust data."""
    return """export type RustCrateGroup =
  | "core"
  | "supporting"
  | "development"
  | "deprecated";

export interface RustCrate {
  name: string;
  summary: string;
  meta: string;
  version: string;
  group: RustCrateGroup;
  docsHref: string;
  cratesHref: string;
  installCommand: string;
  memberPath: string | null;
  sourceHref: string | null;
  badge: string | null;
}

export interface RustBinding {
  name: string;
  language: string;
  summary: string;
  memberPath: string;
  sourceHref: string;
}
"""


def _crate_array(crates: tuple[RustCrate, ...]) -> str:
    """Render the published crate array."""
    entries = ",\n".join(_crate_entry(crate) for crate in crates)
    return f"export const RUST_CRATES: RustCrate[] = [\n{entries}\n];\n"


def _crate_entry(crate: RustCrate) -> str:
    """Render one RustCrate object."""
    values = {
        "name": crate.name,
        "summary": crate.summary,
        "meta": crate.meta,
        "version": crate.version,
        "group": crate.group,
        "docsHref": crate.docs_href,
        "cratesHref": crate.crates_href,
        "installCommand": crate.install_command,
        "memberPath": crate.member_path,
        "sourceHref": crate.source_href,
        "badge": crate.badge,
    }
    body = "\n".join(
        f"    {key}: {json.dumps(value)}," for key, value in values.items()
    )
    return f"  {{\n{body}\n  }}"


def _binding_array(bindings: tuple[RustBinding, ...]) -> str:
    """Render the source binding array."""
    entries = ",\n".join(_binding_entry(binding) for binding in bindings)
    return f"export const RUST_BINDINGS: RustBinding[] = [\n{entries}\n];\n"


def _binding_entry(binding: RustBinding) -> str:
    """Render one RustBinding object."""
    values = {
        "name": binding.name,
        "language": binding.language,
        "summary": binding.summary,
        "memberPath": binding.member_path,
        "sourceHref": binding.source_href,
    }
    body = "\n".join(
        f"    {key}: {json.dumps(value)}," for key, value in values.items()
    )
    return f"  {{\n{body}\n  }}"


def render_page(reference: RustReference) -> str:
    """Render the thin Fern MDX page and its agent-readable twin."""
    return (
        "---\n"
        "# SPDX-FileCopyrightText: Copyright (c) 2025-2026 NVIDIA CORPORATION "
        "& AFFILIATES. All rights reserved.\n"
        "# SPDX-License-Identifier: Apache-2.0\n"
        "title: Rust API\n"
        "subtitle: Published Dynamo crates with release-pinned docs.rs links.\n"
        "---\n\n"
        f"{MDX_GENERATED_MARKER}\n\n"
        'import { ReferenceStyles } from "@/components/ReferenceStyles";\n'
        'import { ApiRustIndex } from "@/components/ApiRustIndex";\n\n'
        "<ReferenceStyles />\n\n"
        "<ApiRustIndex />\n\n"
        "<llms-only>\n\n"
        f"{_llms_markdown(reference)}\n\n"
        "</llms-only>\n"
    )


def _llms_markdown(reference: RustReference) -> str:
    """Render grouped crate tables for Markdown and agent exports."""
    parts = [
        f"Dynamo publishes {len(reference.crates)} Rust crates for "
        f"release `{reference.workspace_version}`."
    ]
    for group, label in GROUP_LABELS.items():
        crates = [crate for crate in reference.crates if crate.group == group]
        if crates:
            parts.extend([f"### {label}", _crate_table(crates)])
    parts.extend(["### Language Bindings", _binding_table(reference.bindings)])
    return "\n\n".join(parts)


def _crate_table(crates: list[RustCrate]) -> str:
    """Render one compact Markdown crate table."""
    rows = [
        "| Crate | Summary | Version | Install |",
        "| --- | --- | --- | --- |",
    ]
    for crate in crates:
        name = f"[`{crate.name}`]({crate.docs_href})"
        rows.append(
            f"| {name} | {_cell(crate.summary)} | `{crate.version}` | "
            f"`{crate.install_command}` |"
        )
    return "\n".join(rows)


def _binding_table(bindings: tuple[RustBinding, ...]) -> str:
    """Render the repository binding table."""
    rows = [
        "| Binding | Language | Summary | Source |",
        "| --- | --- | --- | --- |",
    ]
    for binding in bindings:
        source = f"[`{binding.member_path}`]({binding.source_href})"
        rows.append(
            f"| `{binding.name}` | {binding.language} | "
            f"{_cell(binding.summary)} | {source} |"
        )
    return "\n".join(rows)


def _cell(text: str) -> str:
    """Escape text for a Markdown table cell."""
    return escape_mdx_table_cell(text, empty="")
